effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      #define usePixelation false
      #define flickerFreq 1400.
      #define flickerSpeed 30.
      #define flickerIntensity .1
      #define motionblur .3

      #define iters 70
      // #define lineCountY 50./3.
      #define minDst .001
      // #define lineWidth .2
      // #define lineCountX 35.
      // #define lineCountY 50./3.
      #define speed 6.

      #define pixelsize .2

      // #define gridColor vec3(.2,.05,1.)


      float smin( float a, float b, float k )
      {
          float h = clamp( 0.5+0.5*(b-a)/k, 0.0, 1.0 );
          return mix( b, a, h ) - k*h*(1.0-h);
      }

      float noise(vec2 seed) {
       return fract(sin(dot(seed, vec2(12.9898,4.1414)))*43758.5453);
      }
      float getHeight(vec2 uv) {
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
          float time = iTime;
       uv+=.5;
       uv.y-=time*speed;
       float y1 = floor(uv.y);
       float y2 = floor(uv.y+1.);
       float x1 = floor(uv.x) ;
       float x2 = floor(uv.x+1.);
       float iX1 =mix(noise(vec2(x1, y1)), noise(vec2(x2, y1)),fract(uv.x));
       float iX2 =mix(noise(vec2(x1, y2)), noise(vec2(x2, y2)),fract(uv.x));
       return mix(iX1, iX2, fract(uv.y) );
      }

      float getDistance(vec3 p) {
       return p.z-(1.-cos(p.x*15.))*.03*getHeight(vec2(p.x*lineCountX, p.y*lineCountY/3.));
      }

      float getGridColor(vec2 uv){
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
          float time = iTime;
       float zoom =1., col;
        vec3  cam = vec3(0.,
           1.,
           .1),
              lookat = vec3(0.),
              fwd = normalize(lookat-cam),
              //r = normalize(cross(fwd, vec3(0.,1.,0.))),
             // u = cross(fwd, r),
             u=normalize(cross(fwd, vec3(1.,0.,0.))),
             r=cross(u,fwd),
             c = cam + fwd*zoom,
             i = c+r*uv.x+u*uv.y,
             ray = normalize(i-cam);
       float distSur,
              distOrigin=0.;

       vec3 p = cam;
       for(int i=0; i<iters; i++){
          distSur = getDistance(p);
          if(distOrigin>2.) break;
          if(distSur<minDst) {
           float lineW=lineWidth*distOrigin;
           float xLines=smoothstep(lineW,0.,abs(fract(p.x*lineCountX)-.5));
           float yLines=smoothstep(lineW*2.,0.,abs(fract(p.y*(lineCountY/3.)-time*speed)-.5));
           col+=max(xLines, yLines);
           break;
          }
        p+=ray * distSur;
        distOrigin+=distSur;
       }
       return max(0.,col-(distOrigin*.8));
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((180.0+angle)*0.0174533);
     umefx += vec2((-250.0+position.x), (170.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          float time = iTime;
          // vec3 resolution = iResolution;
          float val= 0.; //(texture2D(backbuffer,vec2(0.)).r);
          float sunHeight = SHIGH;
          // float sunHeight = sin(time*.1)*.1+.1;

        //val=val<=0.?.5:val-.5;
        // vec3 last = vec3(0.0, 0.0, 0.0);

        // vec3 last= texture2DCv(backbuffer, vec2(floor( fragCoord *(usePixelation?pixelsize:1.))/resolution.xy/(usePixelation?pixelsize:1.)) ).rgb;
         // vec2(floor(gl_FragCoord.xy*(usePixelation?pixelsize:1.))/resolution.xy/(usePixelation?pixelsize:1.)) ).rgb;

        vec2 R = iResolution;
        vec2 uv = umefx;
        // uv = ( gl_FragCoord.xy - .5* R ) / R.y + .5;

        uv.y -= sunHeight;
        uv.x += val*.2;

          // sun
          float dist =2.5*length(uv-vec2(0.5,0.5));
          float divisions = 50.0;

          //float pattern = tri(fract(( uv.y + 0.5)* 20.0), 2.0/  divisions, divisionsShift)- (-uv.y + 0.26) * 0.85;
          float pattern = (sin(uv.y*divisions*10. - time*2.)*1.2+uv.y*8.3)*uv.y-1.5+
           sin(uv.x*20.+time*5.)*.01;
          float sunOutline = smoothstep( 0.0,-0.0315, max( dist - 0.315, -pattern)) ;

          vec3 c = vec3(0.0, 0.0, 0.0);
          if(SSS) { c += sunOutline * mix(vec3( 4.0, 0.0, 0.2), vec3(1.0, 1.1, 0.0), uv.y); ///
          }
          // glow
          float glow = max(0.0, 1.0 - dist * 1.25);
          glow = min(glow * glow * glow, 0.325);
          if(SSSS) { c += glow * vec3(1.5, 0.3, (.2+ 1.0)) * 1.1; ///
          }

          uv-=.5;

          uv.y+=sunHeight;

        uv.y+=.18;
        if(uv.y<0.1)
           c+=getGridColor(uv)*4.*gridColor.rgb;
           // c+=getGridColor(uv)*4.*gridColor;
          float p=.1;
           fragColor=1.0*(
             1.3+sin(time*flickerSpeed+uv.y*flickerFreq)*flickerIntensity
            )*vec4(
      	   //vec3(mix(c, last,motionblur))
      	   c
            ,1.0);
           float scanline=smoothstep(1.-.2/flickerFreq,1.,sin(time*flickerSpeed*.1+uv.y*4.));
      	 fragColor*=scanline*.2+1.;

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
